/* eslint-disable @typescript-eslint/no-unused-expressions, space-in-parens */

/// <reference types="@stdlib/types"/>

import zeros = require( '@stdlib/ndarray/zeros' );
import firstIndexEqual = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const y = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	firstIndexEqual<number>( x, y ); // $ExpectType OutputArray
	firstIndexEqual<number>( x, y, 1 ); // $ExpectType OutputArray
	firstIndexEqual<number>( x, y, {} ); // $ExpectType OutputArray
	firstIndexEqual<number>( x, y, 1, {} ); // $ExpectType OutputArray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	const y = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	firstIndexEqual( '5', y ); // $ExpectError
	firstIndexEqual( 5, y ); // $ExpectError
	firstIndexEqual( true, y ); // $ExpectError
	firstIndexEqual( false, y ); // $ExpectError
	firstIndexEqual( null, y ); // $ExpectError
	firstIndexEqual( void 0, y ); // $ExpectError
	firstIndexEqual( {}, y ); // $ExpectError
	firstIndexEqual( ( x: number ): number => x, y ); // $ExpectError

	firstIndexEqual( '5', y, 0 ); // $ExpectError
	firstIndexEqual( 5, y, 0 ); // $ExpectError
	firstIndexEqual( true, y, 0 ); // $ExpectError
	firstIndexEqual( false, y, 0 ); // $ExpectError
	firstIndexEqual( null, y, 0 ); // $ExpectError
	firstIndexEqual( void 0, y, 0 ); // $ExpectError
	firstIndexEqual( {}, y, 0 ); // $ExpectError
	firstIndexEqual( ( x: number ): number => x, y, 0 ); // $ExpectError

	firstIndexEqual( '5', y, {} ); // $ExpectError
	firstIndexEqual( 5, y, {} ); // $ExpectError
	firstIndexEqual( true, y, {} ); // $ExpectError
	firstIndexEqual( false, y, {} ); // $ExpectError
	firstIndexEqual( null, y, {} ); // $ExpectError
	firstIndexEqual( void 0, y, {} ); // $ExpectError
	firstIndexEqual( {}, y, {} ); // $ExpectError
	firstIndexEqual( ( x: number ): number => x, y, {} ); // $ExpectError

	firstIndexEqual( '5', y, 0, {} ); // $ExpectError
	firstIndexEqual( 5, y, 0, {} ); // $ExpectError
	firstIndexEqual( true, y, 0, {} ); // $ExpectError
	firstIndexEqual( false, y, 0, {} ); // $ExpectError
	firstIndexEqual( null, y, 0, {} ); // $ExpectError
	firstIndexEqual( void 0, y, 0, {} ); // $ExpectError
	firstIndexEqual( {}, y, 0, {} ); // $ExpectError
	firstIndexEqual( ( x: number ): number => x, y, 0, {} ); // $ExpectError
}

