// Attached to the function is an `assign` method which returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const y = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const out = zeros( [], {
		'dtype': 'int32'
	});

	firstIndexEqual.assign( x, y, out ); // $ExpectType int32ndarray
	firstIndexEqual.assign( x, y, out, {} ); // $ExpectType int32ndarray
	firstIndexEqual.assign( x, y, 1, out ); // $ExpectType int32ndarray
	firstIndexEqual.assign( x, y, 1, out, {} ); // $ExpectType int32ndarray
}

